'use strict';

// MODULES //

var normalizeAxis = require( './normalize-axis.js' );

/**
* Method to draw the bar.
*
* @private
* @name initialize
* @returns {void}
*/
function initialize() {
	var bckColorArr;
	var frdColorArr;
	var glyphArr;
	var i;
	var j;

	normalizeAxis();
	this._glyphMatrix = [];
	this._backgroundColorMatrix = [];
	this._foregroundColorMatrix = [];
	for ( i = 0; i < this._height; i++ ) {
		bckColorArr = new Array( this._width );
		frdColorArr = new Array( this._width );
		glyphArr = new Array( this._width );
		for ( j = 0; j < this._width; j++ ) {
			glyphArr[ i ][ j ] = this._glyph;
			bckColorArr[ i ][ j ] = this._backgroundColor;
			frdColorArr[ i ][ j ] = this._forwardColor;
		}
		this._glyphMatrix.push( glyphArr );
		this._backgroundColorMatrix.push( bckColorArr );
		this._foregroundColorMatrix.push( frdColorArr );
	}
}

module.exports = initialize;
